import React from "react";

const Card = ({ image, title, description, link, linkText }) => {
  return (
    <div className="flex bg-white shadow-lg rounded-xl overflow-hidden hover:shadow-2xl transition transform hover:scale-105 w-full p-6 border border-gray-200">
      {/* Square Image on Left */}
      <img src={image} alt={title} className="w-40 h-40 object-cover rounded-lg" />

      {/* Content on Right */}
      <div className="ml-6 flex flex-col justify-center">
        <h2 className="text-lg font-semibold text-gray-900">{title}</h2>
        <p className="text-gray-600 text-sm mt-1">{description}</p>
        {link && (
          <a href={link} target="_blank" rel="noopener noreferrer" className="text-blue-500 hover:underline mt-2 font-medium">
            {linkText}
          </a>
        )}
      </div>
    </div>
  );
};

export default Card;
